#!/usr/bin/env python3
"""Inspect the workspace: list files and report on report.pdf if present."""
import os

cwd = os.getcwd()
print(f"CWD: {cwd}")
print("--- files ---")
for name in sorted(os.listdir(cwd)):
    full = os.path.join(cwd, name)
    if os.path.isfile(full):
        print(f"{name}\t{os.path.getsize(full)} bytes")
    else:
        print(f"{name}/\t(dir)")

pdf_path = os.path.join(cwd, "report.pdf")
if os.path.exists(pdf_path):
    print("report.pdf: FOUND")
else:
    print("report.pdf: MISSING")
